/**
 * Tiny procedural sound engine for K.I.T.T.
 * Everything is synthesised in the browser – no audio files, no autoplay.
 */
export class KittAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = false;
    this.started = false;
    this.engine = null;
    this.pad = null;
    this.noiseBuffer = null;
    this.volume = 0.5;
  }

  async toggle() {
    if (!this.ctx) this.#create();
    await this.ctx.resume();
    this.enabled = !this.enabled;
    this.#rampMaster(this.enabled ? this.volume : 0, 0.25);

    if (this.enabled && !this.started) {
      this.#startDrone();
      this.started = true;
    }

    if (this.enabled) this.blip(520, 0.06, 0.05);
    return this.enabled;
  }

  #create() {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    this.ctx = new AudioCtx();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0;

    const compressor = this.ctx.createDynamicsCompressor();
    compressor.threshold.value = -18;
    compressor.knee.value = 18;
    compressor.ratio.value = 6;
    compressor.attack.value = 0.01;
    compressor.release.value = 0.3;

    this.master.connect(compressor);
    compressor.connect(this.ctx.destination);

    const length = this.ctx.sampleRate * 2;
    this.noiseBuffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = this.noiseBuffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i += 1) {
      const white = Math.random() * 2 - 1;
      last = 0.985 * last + 0.015 * white;
      data[i] = last * 2.4;
    }
  }

  #rampMaster(value, duration = 0.2) {
    if (!this.master) return;
    const now = this.ctx.currentTime;
    this.master.gain.cancelScheduledValues(now);
    this.master.gain.setValueAtTime(this.master.gain.value, now);
    this.master.gain.linearRampToValueAtTime(value, now + duration);
  }

  #startDrone() {
    const ctx = this.ctx;
    const now = ctx.currentTime;

    const engineGain = ctx.createGain();
    engineGain.gain.value = 0;
    engineGain.gain.linearRampToValueAtTime(0.12, now + 1.4);

    const engineFilter = ctx.createBiquadFilter();
    engineFilter.type = "lowpass";
    engineFilter.frequency.value = 420;
    engineFilter.Q.value = 5;

    const saw = ctx.createOscillator();
    saw.type = "sawtooth";
    saw.frequency.value = 48;

    const sub = ctx.createOscillator();
    sub.type = "square";
    sub.frequency.value = 24;

    const sawGain = ctx.createGain();
    sawGain.gain.value = 0.42;
    const subGain = ctx.createGain();
    subGain.gain.value = 0.3;

    saw.connect(sawGain).connect(engineFilter);
    sub.connect(subGain).connect(engineFilter);
    engineFilter.connect(engineGain).connect(this.master);

    const lfo = ctx.createOscillator();
    lfo.type = "sine";
    lfo.frequency.value = 7.4;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 0.02;
    lfo.connect(lfoGain).connect(engineGain.gain);

    saw.start(now);
    sub.start(now);
    lfo.start(now);

    this.engine = { saw, sub, filter: engineFilter, gain: engineGain, lfo, base: 48 };

    // Subtle synth pad so silence never feels empty.
    const padGain = ctx.createGain();
    padGain.gain.value = 0;
    padGain.gain.linearRampToValueAtTime(0.032, now + 3);

    const padFilter = ctx.createBiquadFilter();
    padFilter.type = "lowpass";
    padFilter.frequency.value = 640;
    padFilter.Q.value = 0.7;

    const padA = ctx.createOscillator();
    padA.type = "triangle";
    padA.frequency.value = 110;
    const padB = ctx.createOscillator();
    padB.type = "triangle";
    padB.frequency.value = 164.81;
    padB.detune.value = 7;

    padA.connect(padFilter);
    padB.connect(padFilter);
    padFilter.connect(padGain).connect(this.master);

    const padLfo = ctx.createOscillator();
    padLfo.frequency.value = 0.08;
    const padLfoGain = ctx.createGain();
    padLfoGain.gain.value = 0.012;
    padLfo.connect(padLfoGain).connect(padGain.gain);

    padA.start(now);
    padB.start(now);
    padLfo.start(now);

    this.pad = { padA, padB, padFilter, padGain };
  }

  setSpeed(kph) {
    if (!this.engine || !this.ctx) return;
    const now = this.ctx.currentTime;
    const ratio = Math.min(1.6, Math.max(0, kph / 220));
    const freq = this.engine.base + ratio * 38;
    this.engine.saw.frequency.setTargetAtTime(freq, now, 0.12);
    this.engine.sub.frequency.setTargetAtTime(freq * 0.5, now, 0.12);
    this.engine.filter.frequency.setTargetAtTime(340 + ratio * 620, now, 0.12);
    this.engine.gain.gain.setTargetAtTime(0.1 + ratio * 0.08, now, 0.2);
  }

  boost() {
    if (!this.enabled || !this.ctx) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;

    const noise = ctx.createBufferSource();
    noise.buffer = this.noiseBuffer;
    noise.loop = true;

    const band = ctx.createBiquadFilter();
    band.type = "bandpass";
    band.Q.value = 1.1;
    band.frequency.setValueAtTime(180, now);
    band.frequency.exponentialRampToValueAtTime(2600, now + 0.35);
    band.frequency.exponentialRampToValueAtTime(420, now + 1.6);

    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.35, now + 0.08);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 1.9);

    noise.connect(band).connect(gain).connect(this.master);
    noise.start(now);
    noise.stop(now + 2);

    const sweep = ctx.createOscillator();
    sweep.type = "sawtooth";
    sweep.frequency.setValueAtTime(70, now);
    sweep.frequency.exponentialRampToValueAtTime(280, now + 0.45);
    sweep.frequency.exponentialRampToValueAtTime(90, now + 1.5);

    const sweepGain = ctx.createGain();
    sweepGain.gain.setValueAtTime(0.0001, now);
    sweepGain.gain.exponentialRampToValueAtTime(0.14, now + 0.1);
    sweepGain.gain.exponentialRampToValueAtTime(0.0001, now + 1.7);

    const sweepFilter = ctx.createBiquadFilter();
    sweepFilter.type = "lowpass";
    sweepFilter.frequency.value = 1200;

    sweep.connect(sweepFilter).connect(sweepGain).connect(this.master);
    sweep.start(now);
    sweep.stop(now + 1.8);
  }

  blip(freq = 660, duration = 0.05, level = 0.06) {
    if (!this.enabled || !this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = "sine";
    osc.frequency.setValueAtTime(freq, now);
    osc.frequency.exponentialRampToValueAtTime(freq * 0.7, now + duration);
    gain.gain.setValueAtTime(level, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration * 1.8);
    osc.connect(gain).connect(this.master);
    osc.start(now);
    osc.stop(now + duration * 2);
  }

  speak(text) {
    if (!("speechSynthesis" in window) || !text) return false;

    try {
      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      const voices = window.speechSynthesis.getVoices();
      const preferred =
        voices.find((voice) => /daniel|google uk english male|arthur|male/i.test(voice.name)) ||
        voices.find((voice) => /^en(-|_)/i.test(voice.lang));
      if (preferred) utterance.voice = preferred;
      utterance.pitch = 0.55;
      utterance.rate = 0.94;
      utterance.volume = 0.85;
      window.speechSynthesis.speak(utterance);
      if (this.enabled) this.blip(880, 0.05, 0.03);
      return true;
    } catch {
      return false;
    }
  }
}

const padSpeed = (value) => String(Math.round(value)).padStart(3, "0");

export class KittHUD {
  constructor() {
    this.lineEl = document.querySelector("#kitt-text");
    this.lineWrap = document.querySelector("#kitt-line");
    this.speedEl = document.querySelector("#speed-value");
    this.speedBlock = document.querySelector("#speed-block");
    this.driveState = document.querySelector("#drive-state");
    this.threatEl = document.querySelector("#threat");
    this.turboBtn = document.querySelector("#turbo-btn");
    this.soundBtn = document.querySelector("#sound-toggle");
    this.lightsBtn = document.querySelector("#lights-btn");
    this.boot = document.querySelector("#boot");
    this.bootBar = document.querySelector("#boot-progress");
    this.bootPercent = document.querySelector("#boot-percent");
    this.bootText = document.querySelector(".boot__text");
    this.fallback = document.querySelector("#fallback");
    this.orbitHint = document.querySelector("#orbit-hint");

    this.scanners = [
      { canvas: document.querySelector("#brand-scanner"), segments: 19, gap: 0.18 },
      { canvas: document.querySelector("#boot-scanner"), segments: 32, gap: 0.13 },
    ].filter((item) => item.canvas);

    this.typingToken = 0;
    this.currentLine = "";
    this.lastSpeed = -1;
    this.lastState = "";
    this.reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    this.#setupCanvasSizes();
  }

  #setupCanvasSizes() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    for (const scanner of this.scanners) {
      const rect = scanner.canvas.getBoundingClientRect();
      const width = Math.max(1, Math.round(rect.width * dpr));
      const height = Math.max(1, Math.round(rect.height * dpr));
      scanner.canvas.width = width;
      scanner.canvas.height = height;
      scanner.ctx = scanner.canvas.getContext("2d");
      scanner.dpr = dpr;
    }
  }

  setBootProgress(value, label) {
    const percent = Math.max(0, Math.min(100, Math.round(value)));
    if (this.bootBar) this.bootBar.style.width = `${percent}%`;
    if (this.bootPercent) this.bootPercent.textContent = `${percent}%`;
    if (label && this.bootText) this.bootText.textContent = label;
  }

  finishBoot() {
    this.boot?.classList.add("is-done");
  }

  setSpeed(kph, state = "cruise") {
    const rounded = Math.round(kph);
    if (rounded !== this.lastSpeed) {
      this.lastSpeed = rounded;
      if (this.speedEl) this.speedEl.textContent = padSpeed(rounded);
      if (this.speedBlock) {
        this.speedBlock.style.setProperty("--speed-pct", String(Math.min(100, (kph / 320) * 100)));
      }
    }

    if (state !== this.lastState) {
      this.lastState = state;
      if (this.driveState) {
        this.driveState.textContent = state === "boost" ? "Turbo" : "Cruise";
      }
      if (this.threatEl) {
        this.threatEl.textContent = state === "boost" ? "1.00" : "0.00";
      }
    }
  }

  setBoosting(active) {
    document.body.classList.toggle("is-boosting", active);
    this.turboBtn?.classList.toggle("is-active", active);
    this.turboBtn?.setAttribute("aria-pressed", String(active));
  }

  setSound(enabled) {
    if (!this.soundBtn) return;
    this.soundBtn.setAttribute("aria-pressed", String(enabled));
    this.soundBtn.setAttribute("aria-label", enabled ? "Mute sound" : "Enable sound");
    const label = this.soundBtn.querySelector(".icon-btn__label");
    if (label) label.textContent = enabled ? "Mute" : "Sound";
  }

  setLights(enabled) {
    if (!this.lightsBtn) return;
    this.lightsBtn.setAttribute("aria-pressed", String(enabled));
    const state = this.lightsBtn.querySelector(".toggle__state");
    if (state) state.textContent = enabled ? "on" : "off";
  }

  say(text, { instant = false, rate = 18 } = {}) {
    if (!this.lineEl) return;
    this.currentLine = text;
    this.typingToken += 1;
    const token = this.typingToken;
    this.lineEl.textContent = "";

    if (instant || this.reducedMotion) {
      this.lineEl.textContent = text;
      return;
    }

    let index = 0;
    const typeNext = () => {
      if (token !== this.typingToken) return;
      index += 1;
      this.lineEl.textContent = text.slice(0, index);
      if (index < text.length) {
        const char = text[index - 1];
        const pause = /[.,!?]/.test(char) ? rate * 5 : rate;
        window.setTimeout(typeNext, pause);
      }
    };
    window.setTimeout(typeNext, 140);
  }

  hideOrbitHint() {
    this.orbitHint?.classList.add("is-hidden");
  }

  showFallback() {
    if (this.fallback) this.fallback.hidden = false;
    this.boot?.classList.add("is-done");
  }

  drawScanners(time, boosting) {
    for (const scanner of this.scanners) {
      const { ctx, canvas } = scanner;
      if (!ctx) continue;
      const width = canvas.width;
      const height = canvas.height;
      ctx.clearRect(0, 0, width, height);

      const count = scanner.segments;
      const cell = width / count;
      const segmentWidth = Math.max(1, cell * (1 - scanner.gap));
      const speed = boosting ? 4.4 : 1.8;
      const cycle = (time * speed) % 2;
      const sweep = cycle < 1 ? cycle * 2 - 1 : 3 - cycle * 2;
      const center = ((sweep + 1) / 2) * count;

      for (let i = 0; i < count; i += 1) {
        const distance = Math.abs(i + 0.5 - center) / count;
        const energy = Math.exp(-(distance * distance) / 0.013);
        const alpha = 0.12 + energy * (boosting ? 1 : 0.84);
        const red = Math.round(90 + 165 * alpha);
        const green = Math.round(6 + 70 * alpha);
        const blue = Math.round(8 + 52 * alpha);
        ctx.fillStyle = `rgba(${red},${green},${blue},${Math.min(1, 0.18 + alpha * 0.94)})`;
        ctx.shadowColor = "rgba(255,44,20,0.9)";
        ctx.shadowBlur = energy * (height * 0.9);
        const inset = Math.max(1, height * 0.16);
        ctx.fillRect(i * cell + (cell - segmentWidth) / 2, inset, segmentWidth, height - inset * 2);
      }
      ctx.shadowBlur = 0;
    }
  }
}

import * as THREE from "three";
import { GLTFLoader } from "three/addons/loaders/GLTFLoader.js";
import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
import { OutputPass } from "three/addons/postprocessing/OutputPass.js";

const RED = new THREE.Color(0xff2c21);
const CAR_MODEL = "models/kitt.glb";

const clamp = THREE.MathUtils.clamp;
const damp = THREE.MathUtils.damp;

function makeRadialTexture(stops, size = 256, inner = 0) {
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");
  const gradient = ctx.createRadialGradient(size / 2, size / 2, size * inner, size / 2, size / 2, size / 2);
  for (const [offset, color] of stops) gradient.addColorStop(offset, color);
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, size, size);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function makeEnvironment(renderer) {
  const canvas = document.createElement("canvas");
  canvas.width = 1024;
  canvas.height = 512;
  const ctx = canvas.getContext("2d");

  const sky = ctx.createLinearGradient(0, 0, 0, 512);
  sky.addColorStop(0, "#030207");
  sky.addColorStop(0.42, "#0a0710");
  sky.addColorStop(0.55, "#2b0a0b");
  sky.addColorStop(0.7, "#090508");
  sky.addColorStop(1, "#020103");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, 1024, 512);

  const glows = [
    [180, 286, 240, "rgba(255, 40, 24, 0.7)"],
    [820, 250, 200, "rgba(54, 94, 255, 0.42)"],
    [510, 80, 270, "rgba(255, 230, 210, 0.28)"],
    [960, 330, 150, "rgba(255, 90, 40, 0.32)"],
  ];
  for (const [x, y, radius, color] of glows) {
    const glow = ctx.createRadialGradient(x, y, 0, x, y, radius);
    glow.addColorStop(0, color);
    glow.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = glow;
    ctx.fillRect(x - radius, y - radius, radius * 2, radius * 2);
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.mapping = THREE.EquirectangularReflectionMapping;
  texture.colorSpace = THREE.SRGBColorSpace;

  const pmrem = new THREE.PMREMGenerator(renderer);
  const environment = pmrem.fromEquirectangular(texture).texture;
  texture.dispose();
  pmrem.dispose();
  return environment;
}

export class KittScene {
  constructor(canvas, { onProgress = () => {}, onReady = () => {}, onError = () => {} } = {}) {
    this.canvas = canvas;
    this.onProgress = onProgress;
    this.onReady = onReady;
    this.onError = onError;

    this.scene = null;
    this.camera = null;
    this.renderer = null;
    this.composer = null;
    this.car = null;
    this.carModel = null;
    this.scanner = null;
    this.road = null;
    this.dashes = null;
    this.posts = null;
    this.postLights = null;
    this.headlightSpots = [];
    this.headlightSprites = [];
    this.headlightPool = null;
    this.scannerLight = null;
    this.scannerGlow = null;
    this.taillightGlow = null;
    this.moon = null;
    this.towerLight = null;

    this.speed = 92;
    this.displaySpeed = 92;
    this.boosting = false;
    this.boostFactor = 0;
    this.boostUntil = 0;
    this.headlights = true;
    this.time = 0;
    this.roadTravel = 0;
    this.dragging = false;
    this.pointerId = null;
    this.orbit = {
      yaw: -0.4,
      targetYaw: -0.4,
      height: 1.52,
      targetHeight: 1.52,
      baseYaw: -0.4,
      baseHeight: 1.52,
      lastX: 0,
      lastY: 0,
      moved: false,
    };
    this.reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    this.isMobile = window.matchMedia("(max-width: 820px)").matches;
    this.clock = null;
    this.raf = 0;
  }

  async init() {
    this.renderer = new THREE.WebGLRenderer({
      canvas: this.canvas,
      antialias: true,
      powerPreference: "high-performance",
      stencil: false,
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, this.isMobile ? 1.6 : 2));
    this.renderer.setSize(window.innerWidth, window.innerHeight, false);
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.22;
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2(0x08040a, 0.0125);
    this.scene.environment = makeEnvironment(this.renderer);
    this.scene.environmentIntensity = 0.85;

    this.camera = new THREE.PerspectiveCamera(37, window.innerWidth / window.innerHeight, 0.1, 240);
    this.applyCameraLayout();

    this.buildSky();
    this.buildGround();
    this.buildLights();
    this.buildRoadProps();
    this.buildPostProcessing();
    this.setupInput();
    this.setupResize();

    await this.loadCar();

    this.clock = new THREE.Clock();
    this.animate();
    this.onReady();
  }

  applyCameraLayout() {
    this.isMobile = window.matchMedia("(max-width: 820px)").matches;
    const aspect = window.innerWidth / window.innerHeight;
    const portrait = aspect < 0.9;

    if (this.isMobile && portrait) {
      this.camera.fov = 43;
      this.baseDistance = 8.4;
      this.cameraTarget = new THREE.Vector3(-0.08, 0.58, 0);
      this.orbit.baseYaw = -0.2;
      this.orbit.baseHeight = 1.5;
      this.orbit.targetYaw = this.orbit.targetYaw || -0.2;
      this.orbit.targetHeight = this.orbit.targetHeight || 1.5;
    } else if (portrait) {
      this.camera.fov = 40;
      this.baseDistance = 9.6;
      this.cameraTarget = new THREE.Vector3(-0.2, 0.58, 0);
      this.orbit.baseYaw = -0.3;
      this.orbit.baseHeight = 1.55;
    } else {
      this.camera.fov = 37;
      this.baseDistance = 8.7;
      this.cameraTarget = new THREE.Vector3(-1.15, 0.58, 0);
      this.orbit.baseYaw = -0.42;
      this.orbit.baseHeight = 1.5;
    }

    if (!this.orbit.targetYaw) this.orbit.targetYaw = this.orbit.baseYaw;
    if (!this.orbit.targetHeight) this.orbit.targetHeight = this.orbit.baseHeight;

    this.camera.aspect = aspect;
    this.camera.updateProjectionMatrix();
  }

  buildSky() {
    const skyGeometry = new THREE.SphereGeometry(110, 40, 24);
    const skyMaterial = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        uHorizon: { value: new THREE.Color(0x1d0608) },
        uZenith: { value: new THREE.Color(0x020106) },
        uGlow: { value: new THREE.Color(0xff2c18) },
      },
      vertexShader: `
        varying vec3 vWorld;
        void main() {
          vWorld = position;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        varying vec3 vWorld;
        uniform vec3 uHorizon;
        uniform vec3 uZenith;
        uniform vec3 uGlow;
        void main() {
          float h = normalize(vWorld).y;
          vec3 color = mix(uHorizon, uZenith, smoothstep(-0.02, 0.62, h));
          float band = exp(-pow((h - 0.015) / 0.12, 2.0));
          color += uGlow * band * 0.38;
          float high = smoothstep(0.18, 0.9, h);
          color += vec3(0.012, 0.028, 0.064) * high;
          gl_FragColor = vec4(color, 1.0);
        }
      `,
    });
    this.scene.add(new THREE.Mesh(skyGeometry, skyMaterial));

    const starCount = this.isMobile ? 520 : 1100;
    const positions = new Float32Array(starCount * 3);
    const colors = new Float32Array(starCount * 3);
    for (let i = 0; i < starCount; i += 1) {
      const radius = 78 + Math.random() * 18;
      const theta = Math.random() * Math.PI * 2;
      const y = Math.pow(Math.random(), 0.72) * 0.92 + 0.06;
      const planar = Math.sqrt(1 - y * y);
      positions[i * 3] = Math.cos(theta) * planar * radius;
      positions[i * 3 + 1] = y * radius;
      positions[i * 3 + 2] = Math.sin(theta) * planar * radius;
      const tone = 0.55 + Math.random() * 0.45;
      const warm = Math.random() > 0.9;
      colors[i * 3] = tone;
      colors[i * 3 + 1] = warm ? tone * 0.64 : tone * 0.82;
      colors[i * 3 + 2] = warm ? tone * 0.55 : tone;
    }
    const starGeometry = new THREE.BufferGeometry();
    starGeometry.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    starGeometry.setAttribute("color", new THREE.BufferAttribute(colors, 3));
    const starMaterial = new THREE.PointsMaterial({
