    this.composer.addPass(new RenderPass(this.scene, this.camera));
    this.bloom = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      this.boosting ? 0.9 : 0.58,
      0.65,
      0.72,
    );
    this.composer.addPass(this.bloom);
    this.composer.addPass(new OutputPass());
  }

  async loadCar() {
    const loader = new GLTFLoader();
    const gltf = await new Promise((resolve, reject) => {
      loader.load(
        CAR_MODEL,
        resolve,
        (event) => {
          if (event.total) this.onProgress((event.loaded / event.total) * 100);
        },
        reject,
      );
    });

    const root = gltf.scene;
    root.updateMatrixWorld(true);

    let box = new THREE.Box3().setFromObject(root);
    const size = box.getSize(new THREE.Vector3());
    const scale = 4.92 / size.x;
    root.scale.setScalar(scale);
    root.updateMatrixWorld(true);

    box = new THREE.Box3().setFromObject(root);
    const center = box.getCenter(new THREE.Vector3());
    root.position.x -= center.x;
    root.position.z -= center.z;
    root.position.y -= box.min.y;
    root.updateMatrixWorld(true);

    const materials = new Set();
    root.traverse((object) => {
      if (!object.isMesh) return;
      object.castShadow = true;
      object.receiveShadow = true;
      const list = Array.isArray(object.material) ? object.material : [object.material];
      for (const material of list) {
        if (!material) continue;
        materials.add(material);
        material.envMapIntensity = material.name === "DefaultMaterial" ? 1.9 : 1.25;
        if (material.map) material.map.colorSpace = THREE.SRGBColorSpace;
        if (material.emissiveMap) material.emissiveMap.colorSpace = THREE.SRGBColorSpace;
        material.needsUpdate = true;
      }
    });

    const holder = new THREE.Group();
    holder.rotation.y = Math.PI / 2;
    holder.add(root);

    this.car = new THREE.Group();
    this.car.add(holder);
    this.scene.add(this.car);
    this.carModel = root;

    box = new THREE.Box3().setFromObject(this.car);
    this.carBounds = box;

    this.buildScanner(box);
    this.buildTaillight();
    this.onProgress(100);
  }

  buildScanner(box) {
    const size = box.getSize(new THREE.Vector3());
    const frontZ = box.min.z;
    const scannerY = size.y * 0.4;
    const group = new THREE.Group();
    group.position.set(0, scannerY, frontZ - 0.012);

    const housing = new THREE.Mesh(
      new THREE.BoxGeometry(1.02, 0.135, 0.06),
      new THREE.MeshStandardMaterial({
        color: 0x030203,
        roughness: 0.3,
        metalness: 0.75,
        envMapIntensity: 1.2,
      }),
    );
    group.add(housing);

    const count = 15;
    const spacing = 0.06;
    const start = -((count - 1) * spacing) / 2;
    this.scannerSegments = [];
    for (let i = 0; i < count; i += 1) {
      const material = new THREE.MeshStandardMaterial({
        color: 0x120000,
        emissive: 0xff180d,
        emissiveIntensity: 0.1,
        roughness: 0.4,
        metalness: 0.1,
        toneMapped: true,
      });
      const segment = new THREE.Mesh(new THREE.BoxGeometry(0.043, 0.065, 0.018), material);
      segment.position.set(start + i * spacing, 0, 0.041);
      group.add(segment);
      this.scannerSegments.push(material);
    }

    const glowTexture = makeRadialTexture(
      [
        [0, "rgba(255, 56, 34, 0.9)"],
        [0.38, "rgba(255, 28, 14, 0.34)"],
        [1, "rgba(0,0,0,0)"],
      ],
      128,
    );
    this.scannerGlow = new THREE.Sprite(
      new THREE.SpriteMaterial({
        map: glowTexture,
        color: 0xff2a16,
        transparent: true,
        opacity: 0.65,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        toneMapped: false,
      }),
    );
    this.scannerGlow.scale.set(1.85, 0.48, 1);
    this.scannerGlow.position.set(0, 0, 0.02);
    group.add(this.scannerGlow);

    this.car.add(group);
    this.scanner = group;
  }

