  setupInput() {
    const canvas = this.canvas;
    canvas.addEventListener("pointerdown", (event) => {
      if (event.button !== 0 && event.pointerType === "mouse") return;
      this.dragging = true;
      this.pointerId = event.pointerId;
      this.orbit.lastX = event.clientX;
      this.orbit.lastY = event.clientY;
      this.orbit.baseYaw = this.orbit.targetYaw;
      this.orbit.baseHeight = this.orbit.targetHeight;
      this.orbit.moved = false;
      canvas.setPointerCapture(event.pointerId);
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!this.dragging || event.pointerId !== this.pointerId) return;
      const dx = event.clientX - this.orbit.lastX;
      const dy = event.clientY - this.orbit.lastY;
      if (Math.abs(dx) + Math.abs(dy) > 2) this.orbit.moved = true;
      const sensitivity = 0.0028;
      this.orbit.targetYaw = clamp(this.orbit.baseYaw - dx * sensitivity, -0.88, 0.28);
      this.orbit.targetHeight = clamp(this.orbit.baseHeight + dy * 0.0038, 0.85, 2.8);
    });

    const end = (event) => {
      if (event.pointerId !== this.pointerId) return;
      this.dragging = false;
      this.pointerId = null;
      this.orbit.baseYaw = this.orbit.targetYaw;
      this.orbit.baseHeight = this.orbit.targetHeight;
    };
    canvas.addEventListener("pointerup", end);
    canvas.addEventListener("pointercancel", end);

    canvas.addEventListener("wheel", (event) => {
      if (event.ctrlKey) return;
      event.preventDefault();
      this.orbit.targetHeight = clamp(this.orbit.targetHeight + event.deltaY * 0.0012, 0.85, 2.8);
    }, { passive: false });
  }

  setupResize() {
    this.resize = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      this.camera.aspect = width / height;
      this.camera.fov = this.isMobile && width / height < 0.9 ? 43 : 37;
      this.camera.updateProjectionMatrix();
      this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, this.isMobile ? 1.6 : 2));
      this.renderer.setSize(width, height, false);
      this.composer?.setSize(width, height);
      this.applyCameraLayout();
    };
    window.addEventListener("resize", this.resize);
  }

  setHeadlights(enabled) {
    this.headlights = enabled;
    for (const spotlight of this.headlightSpots) spotlight.visible = enabled;
    for (const sprite of this.headlightSprites) sprite.visible = enabled;
    if (this.headlightPool) this.headlightPool.visible = enabled;
  }

  startBoost(duration = 4.2) {
    this.boosting = true;
    this.boostUntil = this.time + duration;
    return this.boosting;
  }

  isBoosting() {
    return this.boosting;
  }

  getSpeed() {
    return this.displaySpeed;
  }

  animate() {
    this.raf = requestAnimationFrame(() => this.animate());
    const delta = Math.min(this.clock.getDelta(), 0.05);
    this.time += delta;

    if (this.boosting && this.time > this.boostUntil) {
      this.boosting = false;
      this.onBoostEnd?.();
    }

    const boostTarget = this.boosting ? 1 : 0;
    this.boostFactor = damp(this.boostFactor, boostTarget, 3.6, delta);
    const targetSpeed = 92 + this.boostFactor * 228;
    this.displaySpeed = damp(this.displaySpeed, targetSpeed, this.boosting ? 5 : 2.4, delta);
    this.speed = this.displaySpeed;

    this.updateCamera(delta);
    this.updateRoad(delta);
    this.updateCar(delta);
    this.updateScanner(delta);
    this.updateHeadlights();
    this.updateAtmosphere(delta);

    if (this.bloom) this.bloom.strength = damp(this.bloom.strength, this.boosting ? 0.92 : 0.58, 4, delta);
    this.composer.render();
  }

  updateCamera(delta) {
    const idleYaw = this.reducedMotion || this.dragging ? 0 : Math.sin(this.time * 0.11) * 0.035;
    const idleHeight = this.reducedMotion || this.dragging ? 0 : Math.sin(this.time * 0.17) * 0.018;
    const desiredYaw = this.orbit.targetYaw + (this.dragging ? 0 : idleYaw);
    const desiredHeight = this.orbit.targetHeight + idleHeight;

    this.orbit.yaw = damp(this.orbit.yaw, desiredYaw, 5.5, delta);
    this.orbit.height = damp(this.orbit.height, desiredHeight, 5.5, delta);

    const distance = this.baseDistance - this.boostFactor * 0.72;
    const target = this.cameraTarget.clone();
    target.y += 0.02 * Math.sin(this.time * 1.3);

    const shake = (this.reducedMotion ? 0 : this.boostFactor) * 0.045;
    const shakeX = (Math.random() - 0.5) * shake;
    const shakeY = (Math.random() - 0.5) * shake * 0.7;

    this.camera.position.set(
      target.x + Math.sin(this.orbit.yaw) * distance + shakeX,
      this.orbit.height + shakeY,
      target.z - Math.cos(this.orbit.yaw) * distance,
    );
    this.camera.lookAt(target);
    this.camera.rotation.z += (Math.random() - 0.5) * shake * 0.06;
  }

  updateRoad(delta) {
    if (!this.road) return;
    const metersPerSecond = (this.displaySpeed / 3.6) * 0.72;
    const travel = metersPerSecond * delta;
    this.roadTravel += travel;

    const matrix = this.postMatrix;
    const rotation = this.postRotation;
    const scale = this.postScale;

    for (let i = 0; i < this.dashData.length; i += 1) {
      let z = this.dashData[i] + travel;
      if (z > 20) z -= 304;
      this.dashData[i] = z - travel + travel;
      const current = this.dashData[i];
      // The stored value IS the position; wrap it directly.
      if (current > 20) this.dashData[i] = current - 304;
      matrix.compose(new THREE.Vector3(-2.55, -0.026, this.dashData[i]), rotation, new THREE.Vector3(1, 1, 1));
      this.dashes.setMatrixAt(i, matrix);
    }
    this.dashes.instanceMatrix.needsUpdate = true;

    let index = 0;
    for (let side = 0; side < 2; side += 1) {
      const x = side === 0 ? -7.15 : 7.15;
      for (let i = 0; i < this.postData.length / 2; i += 1) {
        const entry = this.postData[index];
        entry.z += travel;
        if (entry.z > 12) entry.z -= 273;
        matrix.compose(new THREE.Vector3(x, 0.39, entry.z), rotation, scale);
        this.posts.setMatrixAt(index, matrix);
        matrix.compose(new THREE.Vector3(x, 0.81, entry.z), rotation, scale);
        this.postLights.setMatrixAt(index, matrix);
        index += 1;
      }
    }
    this.posts.instanceMatrix.needsUpdate = true;
    this.postLights.instanceMatrix.needsUpdate = true;

    if (this.headlightPool) {
      this.headlightPool.position.z = -9.5 + Math.sin(this.time * 0.6) * 0.3;
    }
  }

  updateCar(delta) {
    if (!this.car) return;
    const bob = Math.sin(this.time * 1.6) * 0.007 + Math.sin(this.time * 3.7) * 0.0025;
    this.car.position.y = bob;
    this.car.position.z = damp(this.car.position.z, this.boostFactor * 0.52, 4, delta);
    this.car.rotation.x = damp(this.car.rotation.x, this.boostFactor * 0.028, 4, delta);
    this.car.rotation.z = Math.sin(this.time * 1.13) * 0.0025;

    this.carGlow.position.x = this.car.position.x;
    this.carGlow.position.z = this.car.position.z;
    this.carGlow.material.opacity = 0.5 + this.boostFactor * 0.28 + Math.sin(this.time * 2.1) * 0.025;
    this.carGlow.scale.setScalar(1 + this.boostFactor * 0.08);

    if (this.taillightGlow) {
      this.taillightGlow.material.opacity = 0.48 + this.boostFactor * 0.22;
    }
  }

  updateScanner(delta) {
    if (!this.scannerSegments) return;
    const speed = this.boosting ? 5.6 : 2.3;
    const cycle = (this.time * speed) % 2;
    const sweep = cycle < 1 ? cycle * 2 - 1 : 3 - cycle * 2;
    const count = this.scannerSegments.length;

    for (let i = 0; i < count; i += 1) {
      const normalized = (i / (count - 1)) * 2 - 1;
      const distance = normalized - sweep;
      const energy = Math.exp(-(distance * distance) / 0.025);
      const intensity = 0.12 + energy * (this.boosting ? 9.5 : 6.2);
      this.scannerSegments[i].emissiveIntensity = intensity;
    }

    if (this.scannerGlow) {
      this.scannerGlow.material.opacity = 0.35 + (Math.sin(this.time * speed * Math.PI) * 0.5 + 0.5) * 0.45;
    }
    if (this.scannerLight) {
      this.scannerLight.intensity = 1.2 + (Math.sin(this.time * speed * Math.PI) * 0.5 + 0.5) * (this.boosting ? 14 : 8);
    }
  }

  updateHeadlights() {
    if (!this.headlights) return;
    const flicker = 0.96 + Math.sin(this.time * 11.7) * 0.012 + Math.sin(this.time * 23.1) * 0.008;
    for (const spot of this.headlightSpots) spot.intensity = 85 * flicker;
    for (const sprite of this.headlightSprites) {
      const pulse = 0.42 + Math.sin(this.time * 8.3) * 0.025;
      sprite.material.opacity = pulse;
    }
  }

  updateAtmosphere(delta) {
    if (this.towerLight) {
      const pulse = Math.sin(this.time * 2.2) > 0.2 ? 1 : 0.15;
      this.towerLight.material.opacity = pulse;
      this.towerLight.visible = Math.random() > 0.04 || pulse > 0.5;
    }
    if (this.towerGlow) this.towerGlow.material.opacity = 0.35 + Math.sin(this.time * 2.2) * 0.3;
    if (this.moon) this.moon.material.opacity = 0.92 + Math.sin(this.time * 0.4) * 0.03;
  }
}

import "./style.css";
import { KittAudio } from "./audio.js";
import { KittHUD } from "./hud.js";
import { KittScene } from "./scene.js";

const hud = new KittHUD();
const audio = new KittAudio();
const canvas = document.querySelector("#scene");

const idleLines = [
  "Good evening, Michael. K.I.T.T. is online and the scanner is calibrated.",
  "I have checked the engine, the paint, and your driving record. Two of those are perfect.",
  "The highway is clear. Try not to scratch the paint.",
  "All systems nominal. Threat level remains comfortably boring.",
  "I could drive faster. I am simply choosing not to.",
  "Scanner calibrated. I see everything. Including that speed limit.",
];

const boostLines = [
  "Turbo boost engaged. Do try to keep up.",
  "Hold on, Michael. This is going to be loud.",
  "Punch it. I will handle the physics.",
  "Turbo boost. Because subtlety is overrated.",
];

const boostEndLines = [
  "That was entirely unnecessary. I loved it.",
  "We are still alive. Statistically impressive.",
  "Another perfectly executed shortcut.",
  "I have logged that manoeuvre as strictly off the record.",
];

const randomFrom = (list) => list[Math.floor(Math.random() * list.length)];

let lastIdleIndex = -1;
let idleTimer = 0;
let boostSpeakTimer = 0;
let lastLine = "";

function say(text, options) {
  lastLine = text;
  hud.say(text, options);
}

function scheduleIdle(delay = 10000) {
  window.clearTimeout(idleTimer);
  idleTimer = window.setTimeout(() => {
    if (!scene.isBoosting()) {
      let index = Math.floor(Math.random() * idleLines.length);
      if (index === lastIdleIndex) index = (index + 1) % idleLines.length;
      lastIdleIndex = index;
      say(idleLines[index]);
    }
    scheduleIdle(11000 + Math.random() * 4000);
  }, delay);
}

function triggerBoost() {
  if (!scene || scene.ready !== true) return;
  const already = scene.isBoosting();
  scene.startBoost(4.2);
  hud.setBoosting(true);
  audio.boost();
  if (!already) {
    const line = randomFrom(boostLines);
    say(line);
    window.clearTimeout(boostSpeakTimer);
    if (audio.enabled) {
      audio.blip(740, 0.08, 0.05);
    }
  }
  hud.hideOrbitHint();
}

const scene = new KittScene(canvas, {
  onProgress: (value) => {
    const label = value > 74 ? "Loading vehicle profile" : "Establishing connection";
    hud.setBootProgress(value, label);
  },
  onReady: () => {
    hud.setBootProgress(100, "Systems online");
    scene.ready = true;
    window.__KITT_READY__ = true;
    document.body.dataset.ready = "true";
    window.setTimeout(() => hud.finishBoot(), 340);
    window.setTimeout(() => {
      say("Good evening, Michael. K.I.T.T. is online. Scanner calibrated, threat level zero.", { instant: true });
      window.setTimeout(() => {
        say("Are we going for a drive, or shall I keep admiring the paint?", { rate: 17 });
      }, 3000);
      scheduleIdle(13500);
    }, 1100);
  },
  onError: (error) => {
    console.error("K.I.T.T. failed to initialise", error);
    hud.showFallback();
    window.__KITT_READY__ = "error";
  },
});

scene.onBoostEnd = () => {
  hud.setBoosting(false);
  say(randomFrom(boostEndLines));
  scheduleIdle(12000);
};

scene.init().catch((error) => {
  console.error("K.I.T.T. failed to initialise", error);
  hud.showFallback();
  window.__KITT_READY__ = "error";
});

// ---------- Controls ----------

document.querySelector("#turbo-btn")?.addEventListener("click", triggerBoost);

document.querySelector("#sound-toggle")?.addEventListener("click", async () => {
  const enabled = await audio.toggle();
  hud.setSound(enabled);
  if (enabled) {
    say("Audio systems online. I will try to keep the engine noise tasteful.");
  } else {
    say("Audio muted. The silence is almost as dramatic.", { rate: 14 });
  }
});

document.querySelector("#lights-btn")?.addEventListener("click", () => {
  const next = !scene.headlights;
  scene.setHeadlights(next);
  hud.setLights(next);
  audio.blip(next ? 620 : 380, 0.06, 0.05);
  say(next ? "Headlights on. Let there be light." : "Headlights off. I hope you know this road.", { rate: 15 });
});

document.querySelector("#speak-btn")?.addEventListener("click", () => {
  const spoken = audio.speak(lastLine || hud.currentLine);
  if (!spoken) {
    audio.blip(360, 0.12, 0.06);
  }
});

window.addEventListener("keydown", (event) => {
  if (event.code === "Space" && !event.repeat) {
    const active = document.activeElement;
    if (active && /^(INPUT|TEXTAREA|SELECT)$/.test(active.tagName)) return;
    event.preventDefault();
    triggerBoost();
  }

  if (event.code === "KeyL" && !event.repeat) {
    document.querySelector("#lights-btn")?.click();
  }

  if (event.code === "KeyM" && !event.repeat) {
    document.querySelector("#sound-toggle")?.click();
  }
});

canvas.addEventListener("pointermove", () => {
  hud.hideOrbitHint();
}, { once: true });

// ---------- Frame loop ----------

let frame = 0;
function tick(now) {
  frame = requestAnimationFrame(tick);
  if (!scene.ready) return;
  hud.setSpeed(scene.getSpeed(), scene.isBoosting() ? "boost" : "cruise");
  hud.drawScanners(now / 1000, scene.isBoosting());
}

frame = requestAnimationFrame(tick);

document.addEventListener("visibilitychange", () => {
  if (document.hidden) {
    cancelAnimationFrame(frame);
  } else {
    frame = requestAnimationFrame(tick);
  }
});

// A small, intentional hook for automated visual verification and curious humans.
window.__KITT__ = {
  scene,
  hud,
  audio,
  boost: () => triggerBoost(),
  setSpeed: (speed) => {
    scene.displaySpeed = speed;
  },
};

