130:   hud.setLights(next);
131:   audio.blip(next ? 620 : 380, 0.06, 0.05);
132:   say(next ? "Headlights on. Let there be light." : "Headlights off. I hope you know this road.", { rate: 15 });
133: });
134: 
135: document.querySelector("#speak-btn")?.addEventListener("click", () => {
136:   const spoken = audio.speak(lastLine || hud.currentLine);
137:   if (!spoken) {
138:     audio.blip(360, 0.12, 0.06);
139:   }
140: });
141: 
142: window.addEventListener("keydown", (event) => {
143:   if (event.code === "Space" && !event.repeat) {
