import { chromium } from "/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs";

const browser = await chromium.launch({
  headless: false,
  executablePath: "/usr/bin/chromium",
  args: ["--enable-gpu", "--ignore-gpu-blocklist", "--use-angle=vulkan", "--use-vulkan=swiftshader", "--disable-vulkan-surface"],
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on("pageerror", e => errors.push(e.message));
page.on("console", m => { if (m.type() === "error") errors.push(m.text()); });
await page.goto("http://127.0.0.1:3002/", { waitUntil: "networkidle" });
await page.waitForFunction(() => window.__KITT_READY__ === true, null, { timeout: 20000 });
await page.waitForTimeout(1500);

// turbo
await page.click("#turbo-btn");
await page.waitForTimeout(1600);
const boostState = await page.evaluate(() => ({
  speed: document.querySelector(".speed__value")?.textContent,
  boosting: window.__KITT__.scene.isBoosting(),
  bodyClass: document.body.classList.contains("is-boosting"),
  label: document.querySelector(".speed__label")?.textContent,
}));
await page.screenshot({ path: "/tmp/opencode/shots/test-boost.png" });

await page.waitForTimeout(3200);
const afterBoost = await page.evaluate(() => ({
  speed: document.querySelector(".speed__value")?.textContent,
  boosting: window.__KITT__.scene.isBoosting(),
}));

// headlights off
await page.click("#lights-btn");
await page.waitForTimeout(500);
const lights = await page.evaluate(() => ({
  scene: window.__KITT__.scene.headlights,
  text: document.querySelector("#lights-btn")?.textContent?.trim().replace(/\s+/g, " "),
}));
await page.screenshot({ path: "/tmp/opencode/shots/test-lights-off.png" });

// drag orbit
const box = await page.locator("#scene").boundingBox();
await page.mouse.move(box.x + box.width * 0.6, box.y + box.height * 0.6);
await page.mouse.down();
await page.mouse.move(box.x + box.width * 0.42, box.y + box.height * 0.55, { steps: 12 });
await page.mouse.up();
await page.waitForTimeout(900);
const yaw = await page.evaluate(() => window.__KITT__.scene.orbit.targetYaw);
await page.screenshot({ path: "/tmp/opencode/shots/test-orbit.png" });

// sound toggle
await page.click("#sound-toggle");
await page.waitForTimeout(800);
const sound = await page.evaluate(() => ({
  enabled: window.__KITT__.audio.enabled,
  pressed: document.querySelector("#sound-toggle")?.getAttribute("aria-pressed"),
  label: document.querySelector("#sound-toggle")?.textContent?.trim().replace(/\s+/g, " "),
}));

console.log(JSON.stringify({ boostState, afterBoost, lights, yaw, sound, errors }, null, 2));
await browser.close();

